def evaluate_over_seeds(
    sim_cfg: SimConfig,
    train_env: MECEnvironment,
    agents: List[PPOAgent],
    steps: int,
    num_seeds: int,
    base_seed: int,
    reuse_training_topology: bool,
) -> Dict[str, float]:
    torch_rng_state = torch.random.get_rng_state()
    cuda_rng_states = torch.cuda.get_rng_state_all() if torch.cuda.is_available() else None
    runs = []

    for eval_idx in range(num_seeds):
        eval_seed = base_seed + eval_idx * 1000
        torch.manual_seed(eval_seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(eval_seed)
        eval_env = MECEnvironment(sim_cfg, eval_seed)
        if reuse_training_topology:
            eval_env.use_static_topology_from(train_env)
        runs.append(evaluate_hf_ppo(eval_env, agents, steps))

    torch.random.set_rng_state(torch_rng_state)
    if cuda_rng_states is not None:
        torch.cuda.set_rng_state_all(cuda_rng_states)

    result = {
        key: float(np.mean([run[key] for run in runs]))
        for key in runs[0].keys()
    }
    result["max_delay"] = float(np.max([run["max_delay"] for run in runs]))
    return result

def federated_average(
    agents: List[PPOAgent],
    weights: np.ndarray,
    template: PPOAgent,
    parameter_prefixes: Sequence[str] | None = None,
) -> Dict[str, torch.Tensor]:
    total = float(np.sum(weights))
    if total <= 0.0:
        weights = np.ones(len(agents), dtype=np.float64)
        total = float(len(agents))

    avg = copy.deepcopy(template.net.state_dict())
    for key in avg.keys():
        if parameter_prefixes is not None and not key.startswith(tuple(parameter_prefixes)):
            continue
        avg[key] = torch.zeros_like(avg[key])
        for agent, weight in zip(agents, weights):
            avg[key] += agent.net.state_dict()[key] * float(weight / total)
    return avg

def load_state_to_agents(
    agents: List[PPOAgent],
    state_dict: Dict[str, torch.Tensor],
    reset_optimizer: bool = False,
) -> None:
    for agent in agents:
        agent.net.load_state_dict(state_dict)
        if reset_optimizer:
            agent.reset_optimizer()

def mix_state_dict(
    local_state: Dict[str, torch.Tensor],
    global_state: Dict[str, torch.Tensor],
    alpha: float,
    parameter_prefixes: Sequence[str] | None = None,
) -> Dict[str, torch.Tensor]:
    alpha = float(np.clip(alpha, 0.0, 1.0))
    mixed = copy.deepcopy(local_state)
    for key in mixed.keys():
        if parameter_prefixes is not None and not key.startswith(tuple(parameter_prefixes)):
            continue
        mixed[key] = (1.0 - alpha) * local_state[key] + alpha * global_state[key]
    return mixed

