def test_ask_api_model_timeout_maps_to_504(monkeypatch):
    def fake_ask_from_vector_index(**kwargs):
        raise TimeoutError("timeout")

    monkeypatch.setattr(
        "api_main.ask_from_vector_index",
        fake_ask_from_vector_index,
    )

    response = client.post(
        "/ask",
        json={
            "query": "main",
